// Filter to the 'almost ranking' sweet spot — position 6..30, impressions >= 50,
// CTR < 5% (so we have room to grow). Score by uplift potential.
const rows = $input.first().json.rows ?? [];
const CTR_BY_POS = { 1:0.27, 2:0.16, 3:0.10, 4:0.07, 5:0.05, 6:0.04, 7:0.035, 8:0.03, 9:0.027, 10:0.024 };
const targetCTR = (pos) => CTR_BY_POS[Math.max(1, Math.min(10, Math.round(pos)))] || 0.02;

const ops = [];
for (const r of rows) {
  const pos = r.position;
  const imp = r.impressions;
  const ctr = r.ctr;
  if (pos < 6 || pos > 30) continue;
  if (imp < 50) continue;
  if (ctr > 0.05) continue;
  const targetPosition = Math.max(4, Math.round(pos - 8));
  const targetCtrValue = targetCTR(targetPosition);
  const upliftSessionsPerMonth = Math.round(imp * (targetCtrValue - ctr));
  if (upliftSessionsPerMonth < 20) continue;
  ops.push({
    query: r.keys[0],
    page_url: r.keys[1],
    current_position: pos,
    impressions: imp,
    ctr,
    target_position: targetPosition,
    estimated_uplift_sessions: upliftSessionsPerMonth,
    action: pos > 20 ? 'new' : 'refresh',
  });
}
// Sort by uplift desc, top 20
ops.sort((a, b) => b.estimated_uplift_sessions - a.estimated_uplift_sessions);
return ops.slice(0, 20).map(o => ({ json: o }));

